previewCss:
.darma-loader-darma-b10-balloon-inflate { --accent: var(--loader-color, #ef4444); --accent-2: var(--loader-secondary-color, #f59e0b); width: var(--loader-size, 80px); height: var(--loader-size, 80px); position: relative; display: grid; place-items: center; }
.darma-loader-darma-b10-balloon-inflate span { width: 52%; height: 62%; border-radius: 50% 50% 50% 50% / 56% 56% 44% 44%; background: radial-gradient(circle at 38% 32%, color-mix(in srgb, #fff 45%, var(--accent)), var(--accent) 72%, var(--accent-2)); transform-origin: 50% 88%; animation: darma-loader-darma-b10-balloon-inflate-inflate calc(var(--loader-speed, 1s) * 1.8) ease-in-out infinite; position: relative; }
.darma-loader-darma-b10-balloon-inflate span::after { content: ''; position: absolute; bottom: -7%; left: 50%; width: 12%; height: 10%; margin-left: -6%; background: var(--accent-2); clip-path: polygon(50% 0, 100% 100%, 0 100%); }
.darma-loader-darma-b10-balloon-inflate span::before { content: ''; position: absolute; top: 100%; left: 50%; width: 1px; height: calc(var(--loader-size, 80px) * .18); background: color-mix(in srgb, var(--accent) 45%, transparent); }
@keyframes darma-loader-darma-b10-balloon-inflate-inflate { 0%, 100% { transform: scale(.58); } 50% { transform: scale(1); } }

